

import typing

from ..core import enum

T_Result = typing.TypeVar("T_Result")


class DocType(enum.StrEnum):
    """
    The type of document.

    `DOCUMENT_TYPE_PAYSTUB`: A paystub.

    `DOCUMENT_TYPE_BANK_STATEMENT`: A bank statement.

    `DOCUMENT_TYPE_US_TAX_W2`: A W-2 wage and tax statement provided by a US employer reflecting wages earned by the employee.

    `DOCUMENT_TYPE_US_MILITARY_ERAS`: An electronic Retirement Account Statement (eRAS) issued by the US military.

    `DOCUMENT_TYPE_US_MILITARY_LES`: A Leave and Earnings Statement (LES) issued by the US military.

    `DOCUMENT_TYPE_US_MILITARY_CLES`: A Civilian Leave and Earnings Statement (CLES) issued by the US military.

    `DOCUMENT_TYPE_GIG`: Used to indicate that the income is related to gig work. Does not necessarily correspond to a specific document type.

    `DOCUMENT_TYPE_NONE`: Used to indicate that there is no underlying document for the data.

    `DOCUMENT_TYPE_PLAID_GENERATED_PAYSTUB_PDF`: Used to indicate that the PDF for the paystub was generated by Plaid.

    `UNKNOWN`: Document type could not be determined.
    """

    UNKNOWN = "UNKNOWN"
    DOCUMENT_TYPE_PAYSTUB = "DOCUMENT_TYPE_PAYSTUB"
    DOCUMENT_TYPE_BANK_STATEMENT = "DOCUMENT_TYPE_BANK_STATEMENT"
    DOCUMENT_TYPE_US_TAX_W2 = "DOCUMENT_TYPE_US_TAX_W2"
    DOCUMENT_TYPE_US_MILITARY_ERAS = "DOCUMENT_TYPE_US_MILITARY_ERAS"
    DOCUMENT_TYPE_US_MILITARY_LES = "DOCUMENT_TYPE_US_MILITARY_LES"
    DOCUMENT_TYPE_US_MILITARY_CLES = "DOCUMENT_TYPE_US_MILITARY_CLES"
    DOCUMENT_TYPE_GIG = "DOCUMENT_TYPE_GIG"
    DOCUMENT_TYPE_NONE = "DOCUMENT_TYPE_NONE"
    DOCUMENT_TYPE_US_TAX1099MISC = "DOCUMENT_TYPE_US_TAX_1099_MISC"
    DOCUMENT_TYPE_US_TAX1099K = "DOCUMENT_TYPE_US_TAX_1099_K"
    DOCUMENT_TYPE_PLAID_GENERATED_PAYSTUB_PDF = "DOCUMENT_TYPE_PLAID_GENERATED_PAYSTUB_PDF"

    def visit(
        self,
        unknown: typing.Callable[[], T_Result],
        document_type_paystub: typing.Callable[[], T_Result],
        document_type_bank_statement: typing.Callable[[], T_Result],
        document_type_us_tax_w2: typing.Callable[[], T_Result],
        document_type_us_military_eras: typing.Callable[[], T_Result],
        document_type_us_military_les: typing.Callable[[], T_Result],
        document_type_us_military_cles: typing.Callable[[], T_Result],
        document_type_gig: typing.Callable[[], T_Result],
        document_type_none: typing.Callable[[], T_Result],
        document_type_us_tax1099misc: typing.Callable[[], T_Result],
        document_type_us_tax1099k: typing.Callable[[], T_Result],
        document_type_plaid_generated_paystub_pdf: typing.Callable[[], T_Result],
    ) -> T_Result:
        if self is DocType.UNKNOWN:
            return unknown()
        if self is DocType.DOCUMENT_TYPE_PAYSTUB:
            return document_type_paystub()
        if self is DocType.DOCUMENT_TYPE_BANK_STATEMENT:
            return document_type_bank_statement()
        if self is DocType.DOCUMENT_TYPE_US_TAX_W2:
            return document_type_us_tax_w2()
        if self is DocType.DOCUMENT_TYPE_US_MILITARY_ERAS:
            return document_type_us_military_eras()
        if self is DocType.DOCUMENT_TYPE_US_MILITARY_LES:
            return document_type_us_military_les()
        if self is DocType.DOCUMENT_TYPE_US_MILITARY_CLES:
            return document_type_us_military_cles()
        if self is DocType.DOCUMENT_TYPE_GIG:
            return document_type_gig()
        if self is DocType.DOCUMENT_TYPE_NONE:
            return document_type_none()
        if self is DocType.DOCUMENT_TYPE_US_TAX1099MISC:
            return document_type_us_tax1099misc()
        if self is DocType.DOCUMENT_TYPE_US_TAX1099K:
            return document_type_us_tax1099k()
        if self is DocType.DOCUMENT_TYPE_PLAID_GENERATED_PAYSTUB_PDF:
            return document_type_plaid_generated_paystub_pdf()
